import { useState } from 'react';
import { Select, type ListboxOption } from '@design-schema/react';

const COUNTRIES: ListboxOption[] = [
  { value: 'ca', label: 'Canada' },
  { value: 'fr', label: 'France' },
  { value: 'de', label: 'Germany' },
  { value: 'jp', label: 'Japan' },
  { value: 'mx', label: 'Mexico' },
  { value: 'us', label: 'United States' },
];

function Example() {
  const [open, setOpen] = useState(true ?? true);
  return (
    <Select
      label="Country"
      name="country"
      options={COUNTRIES}
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        undefined?.(next);
      }}
    />
  );
}

<Example />

